    if (userProfile) {
        userProfile.classList.add('hidden');
    }
    if (loginError) loginError.style.display = 'none';

    // Kiểm tra và hiển thị tiến độ học tập đã lưu trước đó nếu có
    checkSavedSessionOnStart();

    startBtn?.addEventListener('click', enterRoom);
